export interface CardScheduleState {
  repetitions: number;
  intervalDays: number;
  easeFactor: number;
}

export interface ScheduleResult extends CardScheduleState {
  nextDueDate: string;
}

export function computeNextReview(state: CardScheduleState, grade: number): ScheduleResult {
  let { repetitions, intervalDays, easeFactor } = state;
  if (grade >= 3) {
    if (repetitions === 0) {
      intervalDays = 1;
    } else if (repetitions === 1) {
      intervalDays = 6;
    } else {
      intervalDays = Math.round(intervalDays * easeFactor);
    }
    repetitions += 1;
  } else {
    repetitions = 0;
    intervalDays = 1;
  }
  easeFactor = easeFactor + (0.1 - (5 - grade) * (0.08 + (5 - grade) * 0.02));
  if (easeFactor < 1.3) easeFactor = 1.3;

  const dueDate = new Date();
  dueDate.setDate(dueDate.getDate() + intervalDays);
  return {
    repetitions,
    intervalDays,
    easeFactor: Number(easeFactor.toFixed(2)),
    nextDueDate: dueDate.toISOString().split('T')[0]
  };
}
